import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { HttpException, Version3Client } from 'jira.js';
assert.ok(process.env.VOLTER_WORLD, 'Run the app through its World');
assert.ok(process.env.JIRA_API_TOKEN, 'The World issues the account API token as JIRA_API_TOKEN');
// As Twin's on-call agent constructs it: the site's URL, Basic authentication by the account's email and API token
const jira = new Version3Client({ host: 'https://acme.atlassian.net', authentication: { basic: { email: 'agent@acme.example', apiToken: process.env.JIRA_API_TOKEN } } });

// The token's own account, whose accountId leads the OPS project the agent files into
const me = await jira.myself.getCurrentUser();
assert.equal(me.emailAddress, 'agent@acme.example');
assert.ok(me.accountId, 'the account has an accountId');
const project = await jira.projects.createProject({ key: 'OPS', name: 'Operations', projectTypeKey: 'software', leadAccountId: me.accountId });
assert.equal(project.key, 'OPS');

// The agent's call, unchanged: a Task with an ADF description and the triaged priority
const verdict = 'SEVERITY: high — checkout fails on Safari after the payment step';
const ticket = await jira.issues.createIssue({
  fields: { project: { key: 'OPS' }, issuetype: { name: 'Task' }, summary: 'world/web#1: Checkout fails on Safari', description: { version: 1, type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: verdict }] }] }, priority: { name: 'High' } },
});
assert.match(String(ticket.key), /^OPS-\d+$/);
assert.ok(String(ticket.self).endsWith(`/rest/api/3/issue/${ticket.id}`));

// The filed ticket as the on-call engineer opens it
const read = await jira.issues.getIssue({ issueIdOrKey: ticket.key, fields: ['summary', 'description', 'priority', 'issuetype', 'status', 'project'] });
assert.equal(read.key, ticket.key);
assert.equal(read.fields.summary, 'world/web#1: Checkout fails on Safari');
assert.equal(read.fields.priority.name, 'High');
assert.equal(read.fields.issuetype.name, 'Task');
assert.equal(read.fields.project.key, 'OPS');
assert.equal(read.fields.status.name, 'To Do');
assert.equal(read.fields.description.type, 'doc');
assert.equal(read.fields.description.content[0].content[0].text, verdict);
// A ticket key no issue carries is refused, and the client throws its HttpException with the status
await assert.rejects(() => jira.issues.getIssue({ issueIdOrKey: 'OPS-999' }), (e) => e instanceof HttpException && e.status === 404);

const receipt = { project: project.key, ticket: ticket.key, id: ticket.id, verdict };
writeFileSync('first-use-receipt.json', JSON.stringify(receipt, null, 2) + '\n');
console.log(JSON.stringify(receipt));

