import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Version3Client } from 'jira.js';
assert.ok(process.env.VOLTER_WORLD, 'Run the app through its World');
const prior = JSON.parse(readFileSync('first-use-receipt.json', 'utf8'));
const jira = new Version3Client({ host: 'https://acme.atlassian.net', authentication: { basic: { email: 'agent@acme.example', apiToken: process.env.JIRA_API_TOKEN } } });
const read = await jira.issues.getIssue({ issueIdOrKey: prior.ticket, fields: ['summary', 'description', 'priority'] });
assert.equal(read.id, prior.id);
assert.equal(read.fields.summary, 'world/web#1: Checkout fails on Safari');
assert.equal(read.fields.priority.name, 'High');
assert.equal(read.fields.description.content[0].content[0].text, prior.verdict);
const projects = await jira.projects.searchProjects({});
assert.ok(projects.values.some((p) => p.key === prior.project), 'the OPS project is retained');
console.log(JSON.stringify({ retained: true, ticket: read.key, priority: read.fields.priority.name }));
